      "business": {
        "provides": {
          "text": "經營快餐、粥麵及其他餐飲品牌，提供餐飲及外賣。",
          "sources": [
            {
              "sourceId": "cafedecoral2026",
              "printedPage": "17-19",
              "pdfPage": 18,
              "table": null
            }
          ]
        },
        "customers": {
          "text": "個人食客及機構餐飲客戶。",
          "sources": [
            {
              "sourceId": "cafedecoral2026",
              "printedPage": "17-25",
              "pdfPage": 18,
              "table": null
            }
          ]
        },
        "revenueModel": {
          "text": "主要出售食物及飲品。預售現金券及積分形成合約負債，在兌換或到期時確認相關收入。",
          "sources": [
            {
              "sourceId": "cafedecoral2026",
              "printedPage": "204",
              "pdfPage": 205,
              "table": null
            }
          ]
        },
        "costs": {
          "text": "食材及包裝、人工、租賃、能源和店舖維修是主要成本。租金相關成本包含使用權資產折舊及租賃利息，不能只讀損益表的一行租金。",
          "sources": [
            {
              "sourceId": "cafedecoral2026",
              "printedPage": "15",
              "pdfPage": 16,
              "table": null
            },
            {
              "sourceId": "cafedecoral2026",
              "printedPage": "210",
              "pdfPage": 211,
              "table": null
            }
          ]
        },
        "process": [
          {
            "text": "採購食材，按餐單及標準流程備餐。",
            "sources": [
              {
                "sourceId": "cafedecoral2026",
                "printedPage": "17",
                "pdfPage": 18,
                "table": null
              }
            ]
          },
          {
            "text": "在門店或數碼渠道接單和供餐，收款，安排人手及管理門店。",
            "sources": [
              {
                "sourceId": "cafedecoral2026",
                "printedPage": "19",
                "pdfPage": 20,
                "table": null
              }
            ]
          }
        ],
        "influences": {
          "text": "管理層指出，消費意欲、外遊消費、旅客消費和價格競爭壓低銷售及毛利。",
          "sources": [
            {
              "sourceId": "cafedecoral2026",
              "printedPage": "15-16",
              "pdfPage": 16,
              "table": null
            }
          ]
        }
      },
